from collections import Counter

def compute_mode(nums: list[int]) -> list[int]:
    if not nums:
        return []

    counts = Counter(nums)
    max_freq = max(counts.values())

    modes = [val for val, freq in counts.items() if freq == max_freq]
    return sorted(modes)
