def min_coins_bounded(coins: list[int], limits: list[int], target: int) -> int:
    if target == 0:
        return 0

    # dp[i] will store the minimum number of coins needed to make amount i
    # Initialize with infinity
    dp = [float('inf')] * (target + 1)
    dp[0] = 0

    # Iterate through each coin type
    for coin, limit in zip(coins, limits):
        if limit == 0:
            continue

        # To optimize the bounded knapsack problem, we use a temporary array 
        # or process in a way that doesn't reuse the same coin more than 'limit' times.
        # We iterate backwards to avoid using the same coin instance multiple times.
        for amount in range(target, 0, -1):
            # Try using k coins of the current type
            for k in range(1, limit + 1):
                if amount - k * coin >= 0:
                    dp[amount] = min(dp[amount], dp[amount - k * coin] + k)
                else:
                    break

    return dp[target] if dp[target] != float('inf') else -1
