def longest_bitonic_length(nums: list[int]) -> int:
    if not nums:
        return 0

    n = len(nums)

    # LIS[i] stores the length of the longest strictly increasing subsequence ending at index i
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # LDS[i] stores the length of the longest strictly decreasing subsequence starting at index i
    lds = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if nums[i] > nums[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    max_len = 0
    for i in range(n):
        # The bitonic sequence length is (increasing part + decreasing part - 1) 
