def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return matrix

    rows = len(matrix)
    cols = len(matrix[0])
    res = [row[:] for row in matrix]

    num_rings = min(rows, cols) // 2

    for ring_idx in range(num_rings):
        # Define boundaries for the current ring
        r1, c1 = ring_idx, ring_idx
        r2, c2 = rows - 1 - ring_idx, cols - 1 - ring_idx

        # Extract elements of the ring in clockwise order
        elements = []
        # Top row
        for j in range(c1, c2 + 1):
            elements.append(matrix[r1][j])
        # Right column
        for i in range(r1 + 1, r2 + 1):
            elements.append(matrix[i][c2])
        # Bottom row (if exists)
        if r2 > r1:
            for j in range(c2 - 1, c1 - 1, -1):
                elements.append(matrix[r2][j])
        # Left column (if exists)
        if c2 > c1:
            for i in range(r2 - 1, r1, -1):
                elements.append(matrix[i][c1])

        # Rotate elements
        n = len(elements)
        shift = k % n
        # New sequence: elements shifted by k positions clockwise
        # The element at index i moves to (i + shift) % n
        rotated = [None] * n
        for i in range(n):
            rotated[(i + shift) % n] = elements[i]

        # Put rotated elements back into the matrix
        idx = 0
        for j in range(c1, c2 + 1):
            res[r1][j] = rotated[idx]
            idx += 1
        for i in range(r1 + 1, r2 + 1):
            res[i][c2] = rotated[idx]
            idx += 1
        if r2 > r1:
            for j in range(c2 - 1, c1 - 1, -1):
                res[r2][j] = rotated[idx]
                idx += 1
        if c2 > c1:
            for i in range(r2 - 1, r1, -1):
                res[i][c1] = rotated[idx]
                idx += 1

    return res

