from collections import deque

def min_slides(grid: list[str]) -> int:
    if not grid or not grid[0]:
        return -1

    rows = len(grid)
    cols = len(grid[0])
    start_pos = None
    end_pos = None

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start_pos = (r, c)
            elif grid[r][c] == 'E':
                end_pos = (r, c)

    # BFS to find the shortest path in terms of moves
    queue = deque([(start_pos[0], start_pos[1], 0)])
    visited = {start_pos}

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c, dist = queue.popleft()

        if (r, c) == end_pos:
            return dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            # A move is only allowed if the first cell in that direction is not blocked
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
                # Slide until hitting a wall or boundary
                curr_r, curr_c = r, c
                while True:
                    next_r, next_c = curr_r + dr, curr_c + dc
                    if 0 <= next_r < rows and 0 <= next_c < cols and grid[next_r][next_c] != '#':
                        curr_r, curr_c = next_r, next_c
                    else:
                        break

                if (curr_r, curr_c) not in visited:
                    visited.add((curr_r, curr_c))
                    queue.append((curr_r, curr_c, dist + 1))

    return -1
