from collections import deque

def min_slides(grid: list[str]) -> int:
    """
    Calculates the minimum number of 'slides' (moves) to reach the target.
    Assuming the task is to find the shortest path from 'S' to 'E' 
    where '.' is passable and '#' is a wall.
    """
    if not grid or not grid[0]:
        return -1

    rows = len(grid)
    cols = len(grid[0])
    start_pos = None
    end_pos = None

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start_pos = (r, c)
            elif grid[r][c] == 'E':
                end_pos = (r, c)

    if not start_pos or not end_pos:
        return -1

    queue = deque([(start_pos[0], start_pos[1], 0)])
    visited = {start_pos}

    while queue:
        r, c, dist = queue.popleft()

        if (r, c) == end_pos:
            return dist

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and \
               grid[nr][nc] != '#' and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc, dist + 1))

    return -1
