def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    n = len(matrix)

    def multiply(A, B):
        C = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if A[i][k] == 0:
                    continue
                for j in range(n):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % mod
        return C

    # Initialize result as identity matrix
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1 % mod

    # Normalize base matrix entries to be within [0, mod)
    base = [[cell % mod for cell in row] for row in matrix]

    # Binary exponentiation (Exponentiation by Squaring)
    while exp > 0:
        if exp % 2 == 1:
            res = multiply(res, base)
        base = multiply(base, base)
        exp //= 2

    return res
