def expand_template(template: str, values: dict[str, str]) -> str:
    result = []
    i = 0
    n = len(template)

    while i < n:
        # Check for double braces first
        if template.startswith('{{', i):
            result.append('{')
            i += 2
        elif template.startswith('}}', i):
            result.append('}')
            i += 2
        elif template[i] == '{':
            # Look for the nearest closing brace after this one
            end_idx = template.find('}', i + 1)
            if end_idx != -1:
                # Extract the key between { and }
                key = template[i + 1 : end_idx]
                if key in values:
                    result.append(values[key])
                    i = end_idx + 1
                else:
                    # Key not found, keep the placeholder as is
                    result.append('{')
                    i += 1
            else:
                # No closing brace found, treat as ordinary character
                result.append('{')
                i += 1
        else:
            # Ordinary character or a single '}' not part of '}}'
            result.append(template[i])
            i += 1

    return "".join(result)
