def decode_runs(encoded: str) -> str:
    result = []
    i = 0
    n = len(encoded)

    while i < n:
        # Determine the character token
        if encoded[i] == '\\':
            i += 1
            if i < n:
                char = encoded[i]
                i += 1
            else:
                # This case shouldn't happen based on "well formed" constraint
                break
        else:
            char = encoded[i]
            i += 1

        # Check for repetition marker '~'
        if i < n and encoded[i] == '~':
            i += 1
            num_start = i
            while i < n and encoded[i].isdigit():
                i += 1

            # Extract the number of repetitions
            count_str = encoded[num_start:i]
            count = int(count_str) if count_str else 0
            result.append(char * count)
        else:
            # No repetition marker, character appears once
            result.append(char)

    return "".join(result)
