import itertools

def seating_arrangements(guests: list[str], conflicts: list[tuple[str, str]]) -> list[list[str]]:
    if not guests:
        return [[]]

    # Create a set of conflicts for O(1) lookup, ensuring both directions are covered
    conflict_set = set()
    for a, b in conflicts:
        conflict_set.add((a, b))
        conflict_set.add((b, a))

    # Sort guests to ensure permutations are generated in lexicographical order
    sorted_guests = sorted(guests)
    valid_arrangements = []

    # Generate all possible permutations
    for p in itertools.permutations(sorted_guests):
        is_valid = True
        # Check every adjacent pair in the permutation
        for i in range(len(p) - 1):
            if (p[i], p[i+1]) in conflict_set:
                is_valid = False
                break

        if is_valid:
            valid_arrangements.append(list(p))

    return valid_arrangements

