def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    current_balances = balances.copy()
    frozen_accounts = set()
    failed_indices = []

    for i, op in enumerate(ops):
        success = False
        op_type = op[0]

        if op_type == 'deposit':
            if len(op) == 3:
                account, amount = op[1], op[2]
                if account in current_balances and amount > 0 and account not in frozen_accounts:
                    current_balances[account] += amount
                    success = True

        elif op_type == 'withdraw':
            if len(op) == 3:
                account, amount = op[1], op[2]
                if account in current_balances and amount > 0 and account not in frozen_accounts:
                    if current_balances[account] >= amount:
                        current_balances[account] -= amount
                        success = True

        elif op_type == 'transfer':
            if len(op) == 4:
                source, target, amount = op[1], op[2], op[3]
                fee = 2
                if (source in current_balances and target in current_balances and 
                    source != target and amount > 0 and 
                    source not in frozen_accounts and target not in frozen_accounts):
                    if current_balances[source] >= (amount + fee):
                        current_balances[source] -= (amount + fee)
                        current_balances[target] += amount
                        success = True

        elif op_type == 'freeze':
            if len(op) == 2:
                account = op[1]
                if account in current_balances:
                    frozen_accounts.add(account)
                    success = True

        elif op_type == 'unfreeze':
            if len(op) == 2:
                account = op[1]
                if account in current_balances:
                    frozen_accounts.discard(account)
                    success = True

        if not success:
            failed_indices.append(i)

    return current_balances, failed_indices
