from collections import deque

def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    # queues stores a deque of quantities for each item
    queues = {}
    # global_waiting tracks the order of orders across all items to maintain original sequence
    # We store as [item, quantity, is_waiting] to allow marking as shipped
    global_waiting = []

    for kind, item, quantity in events:
        if item not in stock:
            stock[item] = 0
            queues[item] = deque()

        if kind == 'receive':
            stock[item] += quantity
            # Process the queue for this specific item
            while queues[item]:
                next_qty = queues[item][0]
                if stock[item] >= next_qty:
                    stock[item] -= next_qty
