def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    # waiting_queues stores a deque of quantities for each item
    waiting_queues = {}
    # To maintain the global order of waiting items for the final output
    # We store (item, quantity) in a list and use a pointer or filter, 
    # but a simpler way is to track which orders are still pending.
    # However, the requirement says "waiting" is a list of (item, quantity) 
    # in the order they were placed.

    # To track global order of pending orders, we can use a list of references
    # or simply store the orders in a global queue and mark them as processed.
    # A better way: keep a list of all orders and a 'processed' flag.
    all_orders = [] # List of [item, quantity, is_processed]

    for kind, item, quantity in events:
        if item not in stock:
            stock[item] = 0
        if item not in waiting_queues:
            waiting_queues[item] = deque()

        if kind == 'receive':
            stock[item] += quantity
            # Process waiting queue for this specific item
            while waiting_queues[item]:
                next_qty = waiting_queues[item][0]
                if stock[item] >= next_qty:
                    stock[item] -= next_qty
                    waiting_queues[item].popleft()
                    # Mark this specific order as processed in the global list
                    # We need to find the first unprocessed order for this item
                    for order in all_orders:
                        if order[0] == item and not order[2]:
                            order[2] = True
                            break
                else:
                    break

        elif kind == 'order':
            # Check if item can be shipped immediately:
            # 1. No one else is waiting for this item
            # 2. Sufficient stock available
            if not waiting_queues[item] and stock[item] >= quantity:
                stock[item] -= quantity
            else:
                # Add to item-specific queue and global tracking list
                waiting_queues[item].append(quantity)
                all_orders.append([item, quantity, False])

    # Final waiting list: all orders that are not processed
    waiting = [(item, qty) for item, qty, processed in all_orders if not processed]

    return stock, waiting
