from collections import deque

def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    # queues stores a deque of quantities for each item: {item: deque([qty1, qty2, ...])}
    queues = {}
    # To maintain the global order of waiting orders for the final output
    # We store them as (item, quantity) in a list, but we need to track which ones are still there.
    # A better way is to keep a global list of pending orders and remove them, 
    # but since we need to process per-item, we'll use a list of references or just filter at the end.

    # To track the global order of all orders ever made
    all_orders_sequence = []
    # To track if a specific order instance is still waiting
    # We'll store orders as [item, quantity, is_waiting]

    for kind, item, quantity in events:
        if item not in stock:
            stock[item] = 0
        if item not in queues:
            queues[item] = deque()

        if kind == 'receive':
            stock[item] += quantity
            # Process the queue for this specific item
            while queues[item] and stock[item] >= queues[item][0][0]:
                # Get the order reference to mark it as processed
                order_ref, order_qty = queues[item].popleft()
                stock[item] -= order_qty
                order_ref['is_waiting'] = False

        elif kind == 'order':
            # An order is processed immediately ONLY IF:
            # 1. No previous orders for this item are waiting
            # 2. There is enough stock
            if not queues[item] and stock[item] >= quantity:
                stock[item] -= quantity
            else:
                # Create a reference object to track this order globally
                order_ref = {'is_waiting': True}
                all_orders_sequence.append((order_ref, item, quantity))
                queues[item].append((order_ref, quantity))

    # Construct the final waiting list based on the original order of arrival
    waiting = []
    for ref, item, qty in all_orders_sequence:
        if ref['is_waiting']:
            waiting.append((item, qty))

    return stock, waiting
