from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    if not grid or not grid[0]:
        return -1

    rows = len(grid)
    cols = len(grid[0])
    start_pos = None
    end_pos = None

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start_pos = (r, c)
            elif grid[r][c] == 'E':
                end_pos = (r, c)

    # State: (row, col, has_broken_wall)
    # has_broken_wall: 0 if no wall has been broken, 1 if one wall has been broken
    start_r, start_c = start_pos
    queue = deque([(start_r, start_c, 0, 0)]) # (r, c, broken, dist)
    visited = set([(start_r, start_c, 0)])

    while queue:
        r, c, broken, dist = queue.popleft()

        if (r, c) == end_pos:
            return dist

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
