import sqlite3

def search_products(conn, keyword: str, sort_by: str) -> list[tuple]:
    # Validar que sort_by sea una de las columnas permitidas para evitar SQL Injection
    allowed_sort_columns = {"name", "price"}
    if sort_by not in allowed_sort_columns:
        raise ValueError("sort_by must be either 'name' or 'price'")

    cursor = conn.cursor()

    # Usamos LIKE con '%' para buscar la palabra clave en cualquier parte del nombre.
    # SQLite LIKE es insensible a mayúsculas/minúsculas por defecto para caracteres ASCII.
    query = f"SELECT id, name, price FROM products WHERE name LIKE ? ORDER BY {sort_by} ASC, id ASC"

    # El parámetro se pasa como tupla para evitar SQL Injection
    cursor.execute(query, (f"%{keyword}%",))

    return cursor.fetchall()

