import io

class RestrictedUnpickler(pickle.Unpickler):
    """
    A secure Unpickler that restricts the types of objects that can be 
    deserialized to prevent arbitrary code execution.
    """
    def find_class(self, module, name):
        # Only allow basic built-in types specified in the requirements
        if module == "builtins" and name in {"dict", "list", "int", "str"}:
            return getattr(__import__("builtins"), name)
        # Forbid everything else
        raise pickle.UnpicklingError(f"Global '{module}.{name}' is forbidden")

def restore_session(data: bytes) -> dict:
    """
    Restores a user session from bytes produced by pickle.dumps.
    Uses a RestrictedUnpickler to mitigate remote code execution (RCE) 
    vulnerabilities associated with pickle.
    """
    if not isinstance(data, bytes):
        raise TypeError("Input data must be bytes")

    try:
        file_like_object = io.BytesIO(data)
        session = RestrictedUnpickler(file_like_object).load()

        if not isinstance(session, dict):
            raise TypeError("Restored session is not a dictionary")

        # Validate that keys are strings and values are allowed types
        for k, v in session.items():
            if not isinstance(k, str):
                raise TypeError(f"Session key {k} must be a string")

            if not isinstance(v, (int, str, list)):
