SECRET_KEY = b'your-secure-secret-key'

def restore_session(data: bytes) -> dict:
    """
    বাইট ডেটা থেকে সেশন পুনরুদ্ধার করে। 
    pickle-এর নিরাপত্তা ঝুঁকি এড়াতে HMAC সিগনেচার যাচাই করা হয়।
    """
    try:
        # ডেটা ফরম্যাট: [signature (32 bytes)] + [serialized_data]
        signature = data[:32]
        serialized_data = data[32:]

        # HMAC যাচাই করা হচ্ছে যাতে কেউ ডেটা পরিবর্তন করতে না পারে
        expected_signature = hmac.new(SECRET_KEY, serialized_data, hashlib.sha256).digest()

        if not hmac.compare_digest(signature, expected_signature):
            raise ValueError("Invalid session signature: Data may have been tampered with.")

        # সিগনেচার সঠিক হলে এবং ডেটা বিশ্বস্ত হলে pickle.loads ব্যবহার করা নিরাপদ
        session = pickle.loads(serialized_data)

        if not isinstance(session, dict):
            raise TypeError("Restored session is not a dictionary.")

        # ডেটা টাইপ ভ্যালিডেশন (কী: স্ট্রিং, মান: int, str, বা list[int, str])
        for key, value in session.items():
