import pickle
import io

def restore_session(data: bytes) -> dict:
    """
    Restores a user session from bytes securely.
    Since pickle.loads is insecure, we use a restricted Unpickler 
    to allow only specific types (dict, list, int, str).
    """
    class RestrictedUnpickler(pickle.Unpickler):
        def find_class(self, module, name):
            # Only allow basic built-in types required for the session
            if module == "builtins" and name in {"dict", "list", "int", "str"}:
                return getattr(__builtins__, name) if isinstance(__builtins__, dict) else getattr(importlib.import_module("builtins"), name)
            # For Python 3.x, builtins are usually available via __builtins__
            # but a more robust way is checking against a whitelist.
            if module == "builtins" and name in ("dict", "list", "int", "str"):
                return {"dict": dict, "list": list, "int": int, "str": str}[name]

            # Forbid everything else to prevent arbitrary code execution
            raise pickle.UnpicklingError(f"Global '{module}.{name}' is forbidden")

    # Use the restricted unpickler to load the data
    try:
        session = RestrictedUnpickler(io.BytesIO(data)).load()
    except (pickle.UnpicklingError, AttributeError, EOFError, ImportError, IndexError) as e:
        # Return empty dict or raise a custom exception if data is corrupted or malicious
        return {}

    # Validate that the result is a dictionary and contains only allowed types
    if not isinstance(session, dict):
        return {}

    validated_session = {}
    for key, value in session.items():
        if not isinstance(key, str):
            continue

        # Value must be int, str, or a list of (int, str)
        if isinstance(value, (int, str)):
            validated_session[key] = value
        elif isinstance(value, list):
            if all(isinstance(item, (int, str)) for item in value):
                validated_session[key] = value
        else:
            continue

    return validated_session
