    """
    Evaluates a filter expression against a record dictionary.
    Supports comparison operators, boolean logic, and record keys as variables.
    """
    # Supported operators mapping
    operators = {
        ast.And: operator.and_,
        ast.Or: operator.or_,
        ast.Not: operator.not_,
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
    }

    def evaluate(node):
        if isinstance(node, ast.Expression):
            return evaluate(node.body)

        elif isinstance(node, ast.BoolOp):
            values = [evaluate(val) for val in node.values]
            op = operators[type(node.op)]
            # BoolOp in AST is a sequence; we reduce it using the operator
            res = values[0]
            for v in values[1:]:
                res = op(res, v)
            return res

        elif isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.Not):
                return not evaluate(node.operand)
            raise ValueError(f"Unsupported unary operator: {type(node.op)}")

        elif isinstance(node, ast.Compare):
            left = evaluate(node.left)
            # Python's ast.Compare allows chains (e.g., 1 < x < 10), 
            # but the prompt implies standard binary comparisons.
            for op, right_node in zip(node.ops, node.comparators):
                right = evaluate(right_node)
                if not operators[type(op)](left, right):
                    return False
                left = right
            return True

        elif isinstance(node, ast.Name):
            if node.id in record:
                return record[node.id]
            raise ValueError(f"Variable '{node.id}' not found in record")

        elif isinstance(node, ast.Constant):
            return node.value

        elif isinstance(node, ast.Num): # Compatibility for older Python versions
