def evaluate_formula(formula: str, x: float) -> float:
    """
    Evaluates a mathematical formula string for a given value of x.
    Supported: +, -, *, /, **, unary -, parentheses, sqrt, abs, sin, cos.
    """
    # Define the allowed functions and variables
    allowed_names = {
        'x': x,
        'sqrt': math.sqrt,
        'abs': abs,
        'sin': math.sin,
        'cos': math.cos
    }

    try:
        # Parse the formula into an Abstract Syntax Tree (AST)
        tree = ast.parse(formula, mode='eval')
    except SyntaxError as e:
        raise ValueError(f"Syntax error in formula: {e}")

    def _eval(node):
        if isinstance(node, ast.Num):  # For Python < 3.8
            return float(node.n)
        elif isinstance(node, ast.Constant):  # For Python >= 3.8
            if isinstance(node.value, (int, float)):
                return float(node.value)
            raise ValueError(f"Unsupported constant type: {type(node.value)}")

        elif isinstance(node, ast.BinOp):
            left = _eval(node.left)
            right = _eval(node.right)
            if isinstance(node.op, ast.Add):
                return left + right
            elif isinstance(node.op, ast.Sub):
                return left - right
            elif isinstance(node.op, ast.Mult):
                return left * right
            elif isinstance(node.op, ast.Div):
                return left / right
            elif isinstance(node.op, ast.Pow):
                return left ** right
            else:
                raise ValueError(f"Unsupported binary operator: {type(node.op)}")

        elif isinstance(node, ast.UnaryOp):
            operand = _eval(node.operand)
            if isinstance(node.op, ast.USub):
                return -operand
            elif isinstance(node.op, ast.UAdd):
                return operand
            else:
                raise ValueError(f"Unsupported unary operator: {type(node.op)}")

        elif isinstance(node, ast.Call):
            func_node = node.func
            if not isinstance(func_node, ast.Name):
                raise ValueError("Function calls must be simple names.")

            func_name = func_node.id
            if func_name not in allowed_names or callable(allowed_names[func_name]) is False:
                # This check is slightly redundant given the logic below, but safe
                pass 

            if len(node.args) != 1:
                raise ValueError(f"Function {func_name} expects exactly 1 argument.")

            arg_val = _eval(node.args[0])
            func = allowed_names.get(func_name)
            if func is None or not callable(func):
                raise ValueError(f"Unsupported function: {func_name}")

