import re
from urllib.parse import urlparse

def is_allowed_webhook(url: str) -> bool:
    # Check for forbidden characters: backslash, space, or control characters
    for char in url:
        cp = ord(char)
        if char == '\\' or char == ' ' or cp < 32 or cp == 127:
            return False

    # Case-insensitive check for https:// prefix
    if not url.lower().startswith('https://'):
        return False

    try:
        parsed = urlparse(url)
        # urlparse handles the user:password@ prefix automatically
        # netloc contains host and port
        netloc = parsed.netloc
        if not netloc:
            return False

        # Split host and port
        if ':' in netloc:
            host, port_str = netloc.rsplit(':', 1)
            # Port must be absent (handled by logic) or 443
            if port_str != '443':
                return False
        else:
            host = netloc

        # Remove one trailing dot if present
        if host.endswith('.'):
            host = host[:-1]

        if not host:
            return False

        # Host cannot be localhost or end with .localhost (case insensitive)
        host_lower = host.lower()
        if host_lower == 'localhost' or host_lower.endswith('.localhost'):
            return False

        # DNS name validation: two or more labels separated by '.'
        labels = host.split('.')
        if len(labels) < 2:
            return False

        for i, label in enumerate(labels):
            # Every label must be non-empty and consist of ASCII letters, digits, and '-'
            if not label or not re.match(r'^[a-zA-Z0-9-]+$', label):
                return False

            # The last label must consist only of letters
            if i == len(labels) - 1:
                if not re.match(r'^[a-zA-Z]+$', label):
                    return False

        return True
    except Exception:
        return False
