            if len(parts) != 4:
                return False
            for part in parts:
                if len(part) > 1 and part.startswith('0'):
                    return False

        # Check if the IP is global (publicly routable).
        # .is_global is True if the address is not reserved for private, 
        # loopback, link-local, multicast, etc.
        if not ip.is_global:
            return False

        # Additional check for Shared Address Space (100.64.0.0/10)
        # ipaddress.is_global usually handles this, but we ensure it here.
        if ip.version == 4:
            shared_net = ipaddress.ip_network('100.64.0.0/10')
            if ip in shared_net:
                return False

        return True
    except ValueError:
        # Returns False if ip_str is not a valid IP address format
        return False

