import ipaddress

def is_public_ip(ip_str: str) -> bool:
    """
    Checks if the given string is a valid, publicly routable IP address (IPv4 or IPv6).
    """
    try:
        # The ipaddress module handles standard text forms.
        # However, it allows leading zeros in some versions or trailing whitespace.
        # The prompt strictly forbids leading zeros in IPv4 and any surrounding whitespace.

        if not ip_str or ip_str != ip_str.strip():
            return False

        # Strict check for IPv4 leading zeros (e.g., "192.168.0.01" is invalid)
        if '.' in ip_str and ':' not in ip_str:
            parts = ip_str.split('.')
            if len(parts) != 4:
                return False
            for part in parts:
                if not part.isdigit():
                    return False
                if len(part) > 1 and part[0] == '0':
                    return False

        # Create an IP address object
        ip = ipaddress.ip_address(ip_str)

        # Check if the address is globally reachable
        # is_global is True if the address is not reserved for private, 
        # loopback, link-local, multicast, etc.
        if not ip.is_global:
            return False

        # Specific check for the shared address space 100.64.0.0/10
        # ipaddress.is_global usually handles this, but for explicit safety:
        if isinstance(ip, ipaddress.IPv4Address):
            shared_range = ipaddress.IPv4Network('100.64.0.0/10')
            if ip in shared_range:
                return False
            # Broadcast address check (255.255.255.255)
            if ip == ipaddress.IPv4Address('255.255.255.255'):
                return False

        return True

    except (ValueError, AddressValueError):
        # Returns False if the string is not a valid IP address format
        return False
