    def upper_filter(s): return s.upper()
    def lower_filter(s): return s.lower()
    def capitalize_filter(s): return s.capitalize()

    # Create a Jinja2 environment with the specified filters
    env = Environment()
    env.filters['upper'] = upper_filter
    env.filters['lower'] = lower_filter
    env.filters['capitalize'] = capitalize_filter

    # Create the template object
    jinja_template = env.from_string(template)

    # Render the template with the provided variables
