import zipfile

def unzip_member_text(zip_path: str, member: str) -> str:
    """
    Opens the ZIP archive file zip_path and returns the content of the 
    member named member as a UTF-8 decoded string.
    """
    with zipfile.ZipFile(zip_path, 'r') as zf:
        try:
            with zf.open(member) as f:
                return f.read().decode('utf-8')
        except KeyError:
            raise KeyError(f"Member '{member}' not found in archive '{zip_path}'")

