    try:
        clean_ids = list(set(int(i) for i in ids))
    except (ValueError, TypeError):
        # Handle cases where non-numeric strings might be passed
        clean_ids = []
        for i in ids:
            try:
                clean_ids.append(int(i))
            except (ValueError, TypeError):
                continue
        clean_ids = list(set(clean_ids))

