def is_perfect_square(n: int) -> bool:
    """
    Returns True if the non-negative integer n is a perfect square, 
    False otherwise.
    """
    if n < 0:
        return False
    if n == 0:
        return True

    # Using binary search to find if there exists an integer x such that x*x == n
    left, right = 1, n
    while left <= right:
        mid = (left + right) // 2
        square = mid * mid
        if square == n:
            return True
        elif square < n:
            left = mid + 1
        else:
            right = mid - 1

    return False
