def weighted_harmonic_mean(vals: list[float], weights: list[float]) -> float:
    if not vals or len(vals) != len(weights):
        return 0.0

    sum_weights = sum(weights)
    if sum_weights == 0:
        return 0.0

    try:
        # Weighted Harmonic Mean formula: sum(weights) / sum(weight / value)
        denominator = sum(w / v for v, w in zip(vals, weights))
        if denominator == 0:
            return 0.0
        return round(sum_weights / denominator, 3)
    except ZeroDivisionError:
        # Handle cases where a value in vals is 0
        return 0.0
