def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"

    res = []
    is_negative = False

    # Work with absolute value for the loop, but balanced ternary 
    # handles negatives naturally. However, the standard algorithm 
    # is easier to implement by adjusting the remainder.
    temp_n = n
    while temp_n != 0:
        remainder = temp_n % 3
        if remainder == 2:
            res.append("-")
            temp_n = (temp_n + 1) // 3
        elif remainder == 1:
            res.append("+")
            temp_n = temp_n // 3
        else:
            res.append("0")
            temp_n = temp_n // 3

    return "".join(reversed(res))
