def count_climbing_steps(n: int) -> int:
    if n < 0:
        return 0
    if n == 0:
        return 1

    # dp[i] will store the number of ways to reach step i
    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        # Ways to reach step i is the sum of ways to reach (i-1), (i-2), and (i-3)
        ways = dp[i-1]
        if i >= 2:
            ways += dp[i-2]
        if i >= 3:
            ways += dp[i-3]
        dp[i] = ways

    return dp[n]
