def min_coins_bounded(coins: list[int], limits: list[int], target: int) -> int:
    if target == 0:
        return 0

    # dp[i] will store the minimum coins needed to reach amount i
    # Initialize with infinity
    dp = [float('inf')] * (target + 1)
    dp[0] = 0

    for coin, limit in zip(coins, limits):
        if limit == 0:
            continue

        # To optimize the bounded knapsack problem, we use a deque for each remainder
        # when dividing the current amount by the coin value.
        for r in range(coin):
            deque = [] # stores tuples of (value, index)
            for q in range((target - r) // coin + 1):
                val = dp[r + q * coin] - q

                # Maintain the deque in increasing order of values
                while deque and deque[-1][0] >= val:
                    deque.pop()
                deque.append((val, q))

                # Remove elements that are outside the limit window
                if deque[0][1] < q - limit:
                    deque.pop(0)

                # The minimum coins for current amount is the best value in window + q
                dp[r + q * coin] = deque[0][0] + q

    return int(dp[target]) if dp[target] != float('inf') else -1

