import sys

def find_bridges(n: int, edges: list[tuple[int, int]]) -> list[tuple[int, int]]:
    # Increase recursion depth for deep graphs
    sys.setrecursionlimit(max(1000, n + 100))

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    discovery_time = [-1] * n
    low_link = [-1] * n
    bridges = []
    timer = 0

    def dfs(u: int, p: int = -1):
        nonlocal timer
        discovery_time[u] = low_link[u] = timer
        timer += 1

        for v in adj[u]:
            if v == p:
                continue
            if discovery_time[v] != -1:
                # Back-edge
                low_link[u] = min(low_link[u], discovery_time[v])
            else:
                # Tree-edge
                dfs(v, u)
                low_link[u] = min(low_link[u], low_link[v])
                if low_link[v] > discovery_time[u]:
                    bridges.append(tuple(sorted((u, v))))

    for i in range(n):
        if discovery_time[i] == -1:
            dfs(i)

    return sorted(bridges)
