from collections import OrderedDict

def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    """
    Simulates an LRU cache.
    Returns a tuple (results, keys) where results are the outcomes of 'get' operations
    and keys are the final cache keys from least recently used to most recently used.
    """
    if capacity <= 0:
        results = [None for op in operations if op[0] == "get"]
        return results, []

    cache = OrderedDict()
    results = []

    for op in operations:
        op_type = op[0]
        if op_type == "put":
            key, value = op[1], op[2]
            if key in cache:
                cache.move_to_end(key)
            cache[key] = value
            if len(cache) > capacity:
                cache.popitem(last=False)
        elif op_type == "get":
            key = op[1]
            if key in cache:
                cache.move_to_end(key)
                results.append(cache[key])
            else:
                results.append(None)

    return results, list(cache.keys())
