def expand_template(template: str, values: dict[str, str]) -> str:
    result = []
    i = 0
    n = len(template)

    while i < n:
        # Check for {{
        if i + 1 < n and template[i] == '{' and template[i+1] == '{':
            result.append('{')
            i += 2
            continue

        # Check for }}
        if i + 1 < n and template[i] == '}' and template[i+1] == '}':
            result.append('}')
            i += 2
            continue

        # Check for placeholder: { followed by at least one }
        if template[i] == '{':
            # Look for the first '}' appearing after this '{'
            # The prompt says: "any { followed by at least one } starts a placeholder"
            # This implies we look for the first '}' in the remaining string.
            end_idx = template.find('}', i + 1)
            if end_idx != -1:
                key = template[i + 1 : end_idx]
                if key in values:
                    result.append(values[key])
                    i = end_idx + 1
                    continue

        # Default: treat as regular character
        result.append(template[i])
        i += 1

    return "".join(result)
