def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []

    # Sort items in descending order for First-Fit Decreasing strategy
    sorted_sizes = sorted(sizes, reverse=True)

    bins = []
    bin_sums = []

    for size in sorted_sizes:
        if size > capacity:
            raise ValueError(f"Item size {size} exceeds bin capacity {capacity}")

        # Try to place the item in the first bin that can fit it
        placed = False
        for i in range(len(bins)):
            if bin_sums[i] + size <= capacity:
                bins[i].append(size)
                bin_sums[i] += size
                placed = True
                break

        # If it doesn't fit in any existing bin, create a new one
        if not placed:
            bins.append([size])
            bin_sums.append(size)

    return bins

