def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    # Create a copy of balances to avoid modifying the original
    current_balances = balances.copy()
    # Track frozen status for each account
    frozen_status = {account: False for account in balances}
    failed_indices = []

    for i, op in enumerate(ops):
        success = False
        op_type = op[0]

        if op_type == 'deposit':
            if len(op) == 3:
                account, amount = op[1], op[2]
                if account in current_balances and amount > 0 and not frozen_status[account]:
                    current_balances[account] += amount
                    success = True

        elif op_type == 'withdraw':
            if len(op) == 3:
                account, amount = op[1], op[2]
                if account in current_balances and amount > 0 and not frozen_status[account]:
                    if current_balances[account] >= amount:
                        current_balances[account] -= amount
