from collections import deque

def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    # waiting_queues maps item name to a deque of quantities
    waiting_queues = {}
    # global_waiting tracks the order of all waiting orders across all items
    # We store them as [item, quantity, order_id] to handle removals and maintain order
    global_waiting = []
    order_counter = 0

    for kind, item, quantity in events:
        if item not in stock:
            stock[item] = 0
            waiting_queues[item] = deque()

        if kind == 'receive':
            stock[item] += quantity
            # Process waiting queue for this specific item
            while waiting_queues[item]:
                next_qty = waiting_queues[item][0]
                if stock[item] >= next_qty:
                    stock[item] -= next_qty
                    waiting_queues[item].popleft()
                    # Remove this specific order from the global waiting list
                    # We find the first occurrence of this item with this quantity 
                    # that is still in the global list
                    for i in range(len(global_waiting)):
                        if global_waiting[i][0] == item and global_waiting[i][1] == next_qty:
                            # This is tricky because multiple orders can have same qty.
                            # However, the logic requires FIFO per item.
                            # Since we only pop from the left of the item queue, 
                            # we must remove the oldest global order for that item.
                            global_waiting.pop(i)
                            break
                else:
                    break

        elif kind == 'order':
            # Check if there is already a waiting order for this item
            if not waiting_queues[item] and stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting_queues[item].append(quantity)
                global_waiting.append((item, quantity))

    return stock, global_waiting
