def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == "-":
        raise ValueError("Invalid input number")

    # Handle sign
    is_negative = False
    if number.startswith("-"):
        is_negative = True
        number = number[1:]

    # Map characters to values
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    char_to_val = {char: i for i, char in enumerate(digits)}

    # Convert from_base to decimal (base 10)
    decimal_value = 0
    for char in number.lower():
        if char not in char_to_val or char_to_val[char] >= from_base:
            raise ValueError(f"Character {char} is not valid for base {from_base}")
        decimal_value = decimal_value * from_base + char_to_val[char]

    if decimal_value == 0:
        return "0"

    # Convert decimal to to_base
    result = []
    while decimal_value > 0:
        result.append(digits[decimal_value % to_base])
        decimal_value //= to_base

    res_str = "".join(reversed(result))
    return f"-{res_str}" if is_negative else res_str

def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    steps = 0
    max_steps = 1000

    while ip < len(program):
        if steps >= max_steps:
            return None

        instr = program[ip]
        steps += 1

        parts = instr.split()
        cmd = parts[0]

        if cmd == "PUSH":
            try:
                val = int(parts[1])
                stack.append(val)
            except (IndexError, ValueError):
                pass
            ip += 1
        elif cmd == "POP":
            if not stack: return None
            stack.pop()
            ip += 1
        elif cmd == "DUP":
            if not stack: return None
            stack.append(stack[-1])
            ip += 1
        elif cmd == "SWAP":
            if len(stack) < 2: return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
            ip += 1
        elif cmd == "ADD":
            if len(stack) < 2: return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
            ip += 1
        elif cmd == "SUB":
            if len(stack) < 2: return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
            ip += 1
        elif cmd == "MUL":
            if len(stack) < 2: return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
            ip += 1
        elif cmd == "JMP":
            try:
                target = int(parts[1])
                ip = target
            except (IndexError, ValueError):
                ip += 1
        elif cmd == "JZ":
            if not stack: return None
            try:
                target = int(parts[1])
                val = stack.pop()
                if val == 0:
                    ip = target
                else:
                    ip += 1
            except (IndexError, ValueError):
                ip += 1
        else:
            ip += 1

    return stack

