import copy

def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    # Create a deep copy to avoid modifying the original grid
    current_grid = copy.deepcopy(grid)
    rows = len(current_grid)
    cols = len(current_grid[0]) if rows > 0 else 0

    if cols == 0:
        return [[] for _ in range(rows)]

    while True:
        unstable_cell = None
        # Scan for any cell that needs to collapse
        for r in range(rows):
            for c in range(cols):
                if current_grid[r][c] >= 4:
                    unstable_cell = (r, c)
                    break
            if unstable_cell:
                break

        # If no unstable cells are found, the sandpile is stable
        if not unstable_cell:
            break

        # Perform the collapse
        r, c = unstable_cell
        current_grid[r][c] -= 4

        # Distribute to neighbors
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                current_grid[nr][nc] += 1

    return current_grid
