        netloc = parsed.netloc
        if '@' in netloc:
            host_port = netloc.split('@', 1)[1]
        else:
            host_port = netloc

        if ':' in host_port:
            host, port = host_port.rsplit(':', 1)
        else:
            host, port = host_port, None

        # Port must be missing or 443
        if port is not None and port != '443':
            return False

        # Host must end with a '.'
        if not host.endswith('.'):
            return False

        # Remove the final '.' for DNS validation
        dns_name = host[:-1]

        # Host is not localhost and does not end with .localhost
        dns_lower = dns_name.lower()
        if dns_lower == 'localhost' or dns_lower.endswith('.localhost'):
            return False

        # DNS name validation: two or more labels separated by '.'
        labels = dns_name.split('.')
        if len(labels) < 2:
            return False

        for i, label in enumerate(labels):
            # Each label must be non-empty and consist of ASCII letters, digits, and '-'
            if not label or not re.match(r'^[a-zA-Z0-9-]+$', label):
                return False

            # The last label consists only of letters
            if i == len(labels) - 1:
                if not re.match(r'^[a-zA-Z]+$', label):
                    return False

        return True
    except Exception:
        return False
