import zipfile

def unzip_member_text(zip_path: str, member: str) -> str:
    """
    Opens a ZIP archive file and returns the content of the specified member as a UTF-8 string.
    Raises KeyError if the member is not found in the archive.
    """
    with zipfile.ZipFile(zip_path, 'r') as z:
        try:
            with z.open(member) as f:
                return f.read().decode('utf-8')
        except KeyError:
            raise KeyError(f"Member '{member}' not found in archive '{zip_path}'")

