def is_valid_parentheses(s: str) -> bool:
    """
    Checks if the input string s consisting of brackets '(', ')', '[', ']', '{', '}'
    is valid. A string is valid if every opening bracket is closed by a bracket 
    of the same type in the correct order.
    """
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in mapping:
            # Pop the top element from the stack if it's not empty, otherwise assign a dummy value
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return False
        else:
            # It is an opening bracket, push it onto the stack
            stack.append(char)

    return not stack
