def evaluate_expression(expr: str) -> int:
    # Remove spaces
    expr = expr.replace(" ", "")
    pos = 0

    def parse_expression() -> int:
        nonlocal pos
        # Handle + and - (lowest priority)
        res = parse_term()
        while pos < len(expr) and expr[pos] in ('+', '-'):
            op = expr[pos]
            pos += 1
            val = parse_term()
            if op == '+':
                res += val
            else:
                res -= val
        return res

    def parse_term() -> int:
        nonlocal pos
        # Handle * and /
        res = parse_unary()
        while pos < len(expr) and expr[pos] in ('*', '/'):
            op = expr[pos]
            pos += 1
            val = parse_unary()
            if op == '*':
                res *= val
            else:
                if val == 0:
                    raise ZeroDivisionError("division by zero")
                # Truncate toward zero
                res = int(res / val)
        return res

    def parse_unary() -> int:
        nonlocal pos
        # Handle unary minus
        if pos < len(expr) and expr[pos] == '-':
            pos += 1
            return -parse_unary()
        return parse_exponent()

    def parse_exponent() -> int:
        nonlocal pos
        # Handle ^ (right-associative)
        res = parse_primary()
        if pos < len(expr) and expr[pos] == '^':
            pos += 1
            # Right associativity: call parse_exponent recursively
            res = res ** parse_exponent()
        return res

    def parse_primary() -> int:
        nonlocal pos
        if expr[pos] == '(':
            pos += 1
            res = parse_expression()
            pos += 1  # skip ')'
            return res
        else:
            # Parse non-negative integer literal
            start = pos
            while pos < len(expr) and expr[pos].isdigit():
                pos += 1
            return int(expr[start:pos])

    return parse_expression()
