def parse_csv(text: str) -> list[list[str]]:
    if not text:
        return []

    results = []
    current_record = []
    current_field = []

    i = 0
    n = len(text)

    while i < n:
        char = text[i]

        if char == '"':
            # Quoted field
            i += 1  # Skip opening quote
            while i < n:
                if text[i] == '"':
                    if i + 1 < n and text[i+1] == '"':
                        current_field.append('"')
                        i += 2
                    else:
                        i += 1  # Skip closing quote
                        break
                else:
                    current_field.append(text[i])
                    i += 1
        else:
            # Unquoted field
            while i < n and char not in (',', '\n'):
                current_field.append(char)
                i += 1
                if i < n:
                    char = text[i]

        # After a field is processed, check for delimiter
        if i < n:
            if text[i] == ',':
                current_record.append("".join(current_field))
                current_field = []
                i += 1
                # Handle case where comma is at the end of the line or text
                if i == n or text[i] == '\n':
                    # This will be handled by the newline/end logic
                    pass
            elif text[i] == '\n':
                current_record.append("".join(current_field))
                results.append(current_record)
                current_record = []
                current_field = []
                i += 1
        else:
            # End of text
            current_record.append("".join(current_field))
            results.append(current_record)

    # Handle trailing newline: the prompt says a newline at the very end 
    # does not start a new record.
    if text.endswith('\n'):
        results.pop()

    return results
