def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    pc = 0
    instructions_executed = 0

    while pc < len(program):
        if instructions_executed >= 1000:
            raise RuntimeError("Maximum instruction limit exceeded")

        instr_raw = program[pc]
        parts = instr_raw.split()
        op = parts[0]

        instructions_executed += 1

        if op == "PUSH":
            if len(parts) < 2:
                raise ValueError("PUSH requires an integer argument")
            stack.append(int(parts[1]))
            pc += 1
        elif op == "POP":
            if not stack:
                raise ValueError("Stack underflow on POP")
            stack.pop()
            pc += 1
        elif op == "DUP":
            if not stack:
                raise ValueError("Stack underflow on DUP")
            stack.append(stack[-1])
            pc += 1
        elif op == "SWAP":
            if len(stack) < 2:
                raise ValueError("Stack underflow on SWAP")
            stack[-1], stack[-2] = stack[-2], stack[-1]
            pc += 1
        elif op == "ADD":
            if len(stack) < 2:
                raise ValueError("Stack underflow on ADD")
            a = stack.pop(-2) # This is wrong logic for pop, should be:
            # Correct way to get a (bottom) and b (top)
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
            pc += 1
        elif op == "SUB":
            if len(stack) < 2:
                raise ValueError("Stack underflow on SUB")
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
            pc += 1
        elif op == "MUL":
            if len(stack) < 2:
                raise ValueError("Stack underflow on MUL")
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
            pc += 1
        elif op == "JMP":
            if len(parts) < 2:
                raise ValueError("JMP requires a target index")
            pc = int(parts[1])
        elif op == "JZ":
            if len(parts) < 2:
                raise ValueError("JZ requires a target index")
            if not stack:
                raise ValueError("Stack underflow on JZ")
            val = stack.pop()
            if val == 0:
                pc = int(parts[1])
            else:
                pc += 1
        elif op == "HALT":
            break
        else:
            raise ValueError(f"Unknown instruction: {op}")

    return stack
