from collections import deque

def min_slides(grid: list[str]) -> int:
    if not grid or not grid[0]:
        return -1

    rows = len(grid)
    cols = len(grid[0])
    start_pos = None
    end_pos = None

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start_pos = (r, c)
            elif grid[r][c] == 'E':
                end_pos = (r, c)

    if not start_pos or not end_pos:
        return -1

    queue = deque([(start_pos[0], start_pos[1], 0)])
    visited = {start_pos}

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c, dist = queue.popleft()

        if (r, c) == end_pos:
            return dist

        for dr, dc in directions:
            nr, nc = r, c
            # Check if the first move in this direction is possible
            if not (0 <= r + dr < rows and 0 <= c + dc < cols and grid[r + dr][c + dc] != '#'):
                continue

            # Slide until hitting a wall or boundary
            while 0 <= nr + dr < rows and 0 <= nc + dc < cols and grid[nr + dr][nc + dc] != '#':
                nr += dr
                nc += dc

            if (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc, dist + 1))

    return -1
