def min_slides(grid: list[str]) -> int:
    """
    Calculates the minimum number of moves to slide a puck from 'S' to 'E'.
    The puck slides in a direction until it hits a wall '#' or the grid boundary.
    """
    if not grid or not grid[0]:
        return -1

    rows = len(grid)
    cols = len(grid[0])
    start_pos = None
    end_pos = None

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start_pos = (r, c)
            elif grid[r][c] == 'E':
                end_pos = (r, c)

    # BFS to find the shortest path
    queue = deque([(start_pos[0], start_pos[1], 0)])
    visited = {start_pos}

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c, dist = queue.popleft()

        if (r, c) == end_pos:
            return dist

        for dr, dc in directions:
            # Check if the first step is possible
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
                # Slide until hitting a wall or boundary
                curr_r, curr_c = r, c
                while True:
