    """
    Computes (matrix^exp) % mod using binary exponentiation.
    """
    n = len(matrix)

    def multiply(A: list[list[int]], B: list[list[int]]) -> list[list[int]]:
        C = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if A[i][k] == 0:
                    continue
                for j in range(n):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % mod
        return C

    # Initialize result as identity matrix I
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1 % mod

    # Base matrix reduced modulo mod
    base = [[cell % mod for cell in row] for row in matrix]

    while exp > 0:
        if exp % 2 == 1:
