def expand_template(template: str, values: dict[str, str]) -> str:
    """
    Expands placeholders in the template string using the provided values dictionary.

    - {{ -> {
    - }} -> }
    - {key} -> values[key] if key exists, otherwise {key}
    - { without a closing } or } without a preceding { are treated as literals.
    """
    result = []
    i = 0
    n = len(template)

    while i < n:
        # Handle double braces first
        if template.startswith('{{', i):
            result.append('{')
            i += 2
            continue
        if template.startswith('}}', i):
            result.append('}')
            i += 2
