def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end:
        return []

    # Filter invalid intervals and clip them to the day boundaries
    clipped_busy = []
    for start, end in busy:
        if start < end:
            # Clip to day_start and day_end
            s = max(start, day_start)
            e = min(end, day_end)
            if s < e:
                clipped_busy.append((s, e))

    # Sort intervals by start time
    clipped_busy.sort()

    # Merge overlapping or adjacent intervals
    merged = []
    if clipped_busy:
        curr_start, curr_end = clipped_busy[0]
        for i in range(1, len(clipped_busy)):
            next_start, next_end = clipped_busy[i]
            if next_start <= curr_end:
                curr_end = max(curr_end, next_end)
            else:
                merged.append((curr_start, curr_end))
                curr_start, curr_end = next_start, next_end
        merged.append((curr_start, curr_end))

    # Find gaps between merged intervals within the day boundaries
    free = []
    last_end = day_start

    for start, end in merged:
        if start - last_end >= min_len:
            free.append((last_end, start))
        last_end = max(last_end, end)

    # Check for a final gap after the last busy interval
    if day_end - last_end >= min_len:
        free.append((last_end, day_end))

    return free
