from collections import deque

def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    # queues stores the waiting orders for each item: {item: deque([(order_id, quantity), ...])}
    queues = {}
    # global_waiting stores the order_id of orders that are currently waiting
    global_waiting = []
    # To keep track of the original order of events to maintain the waiting list
    order_counter = 0

    # We need to track which orders are still pending globally
    # pending_orders: {order_id: (item, quantity)}
    pending_orders = {}

    for kind, item, quantity in events:
        if item not in stock:
            stock[item] = 0
        if item not in queues:
            queues[item] = deque()

        if kind == 'receive':
            stock[item] += quantity
            # Process the queue for this specific item
            while queues[item]:
                order_id, q_qty = queues[item][0]
                if stock[item] >= q_qty:
                    stock[item] -= q_qty
                    queues[item].popleft()
                    # Remove from global tracking
                    if order_id in pending_orders:
                        del pending_orders[order_id]
                else:
                    break

        elif kind == 'order':
            # An order is processed immediately if:
            # 1. No other orders for this item are waiting
            # 2. There is enough stock
            if not queues[item] and stock[item] >= quantity:
                stock[item] -= quantity
            else:
                # Add to item-specific queue and global tracking
                queues[item].append((order_counter, quantity))
                pending_orders[order_counter] = (item, quantity)
                global_waiting.append(order_counter)
                order_counter += 1

    # Filter global_waiting to keep only those still in pending_orders
    final_waiting = [pending_orders[oid] for oid in global_waiting if oid in pending_orders]

    return stock, final_waiting
