def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    steps = 0
    max_steps = 1000

    while ip < len(program):
        if steps >= max_steps:
            return None

        instruction = program[ip]
        parts = instruction.split()
        cmd = parts[0]

        steps += 1

        if cmd == "PUSH":
            try:
                val = int(parts[1])
                stack.append(val)
                ip += 1
            except (IndexError, ValueError):
                return None
        elif cmd == "POP":
            if not stack:
                return None
            stack.pop()
            ip += 1
        elif cmd == "DUP":
            if not stack:
                return None
            stack.append(stack[-1])
            ip += 1
        elif cmd == "SWAP":
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
            ip += 1
        elif cmd in ("ADD", "SUB", "MUL"):
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            if cmd == "ADD":
                stack.append(a + b)
            elif cmd == "SUB":
                stack.append(a - b)
            elif cmd == "MUL":
                stack.append(a * b)
            ip += 1
        elif cmd == "JMP":
            try:
                target = int(parts[1])
                if target < 0:
                    return None
                ip = target
            except (IndexError, ValueError):
                return None
        elif cmd == "JZ":
            if not stack:
                return None
            val = stack.pop()
            try:
                target = int(parts[1])
                if target < 0:
                    return None
                if val == 0:
                    ip = target
                else:
                    ip += 1
            except (IndexError, ValueError):
                return None
        else:
            # Every other instruction execution continues with the next instruction
            ip += 1

    return stack
