def shortest_path_one_break(grid: list[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])
    start_pos = None
    end_pos = None

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start_pos = (r, c)
            elif grid[r][c] == 'E':
                end_pos = (r, c)

    # State: (row, col, has_broken_wall)
    # visited[row][col][0] -> visited without breaking a wall
