import copy

def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    # Create a deep copy to avoid modifying the original grid
    current_grid = copy.deepcopy(grid)
    rows = len(current_grid)
    cols = len(current_grid[0])

    while True:
        to_topple = []
        # Identify all cells that need to topple
        for r in range(rows):
            for c in range(cols):
                if current_grid[r][c] >= 4:
                    to_topple.append((r, c))

        # If no cells need toppling, the sandpile is stable
        if not to_topple:
            break

        # Topple all unstable cells identified in this pass
        # Note: The problem states the order doesn't change the result.
        # We process them one by one to simulate the process.
        for r, c in to_topple:
            current_grid[r][c] -= 4
            # Neighbors: Up, Down, Left, Right
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    current_grid[nr][nc] += 1

    return current_grid
