import ast
import operator

def evaluate_expression(expression: str) -> float:
    """
    Evaluates an arithmetic expression string and returns the result as a float.
    Supports +, -, *, /, **, unary -, and parentheses.
    """
    if not expression or expression.strip() == "":
        raise ValueError("Expression cannot be empty.")

    # Define supported operators
    operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Pow: operator.pow,
        ast.USub: operator.neg,
        ast.UAdd: operator.pos,
    }

    def _eval(node):
        if isinstance(node, ast.Num):  # For Python < 3.8
            return float(node.n)
        elif isinstance(node, ast.Constant):  # For Python >= 3.8
            if isinstance(node.value, (int, float)):
                return float(node.value)
            raise ValueError(f"Unsupported constant: {node.value}")
        elif isinstance(node, ast.BinOp):
            op_type = type(node.op)
            if op_type not in operators:
                raise ValueError(f"Unsupported binary operator: {op_type}")

            left = _eval(node.left)
            right = _eval(node.right)

            try:
                return float(operators[op_type](left, right))
            except ZeroDivisionError:
                raise ZeroDivisionError("division by zero")
            except OverflowError:
                raise ValueError("Result too large to represent")
        elif isinstance(node, ast.UnaryOp):
            op_type = type(node.op)
            if op_type not in operators:
                raise ValueError(f"Unsupported unary operator: {op_type}")
            return float(operators[op_type](_eval(node.operand)))
        elif isinstance(node, ast.Expr):
            return _eval(node.value)
        else:
            raise ValueError(f"Unsupported expression component: {type(node)}")

    try:
        # Parse the expression into an AST
        # mode='eval' ensures it's a single expression, not a script
        tree = ast.parse(expression.strip(), mode='eval')
        return _eval(tree.body)
    except (SyntaxError, TypeError, KeyError) as e:
        raise ValueError(f"Invalid expression: {e}")
