        # mode='eval' ensures it's treated as a single expression.
        tree = ast.parse(expression, mode='eval')

        # We use a recursive helper to evaluate the AST nodes safely.
        # This avoids using eval() directly on raw strings for security.
        def _eval(node):
            if isinstance(node, ast.Num):  # Deprecated in 3.8+, but kept for compatibility
                return float(node.n)
            elif isinstance(node, ast.Constant): # Python 3.8+
                if isinstance(node.value, (int, float)):
                    return float(node.value)
                raise ValueError(f"Unsupported constant type: {type(node.value)}")
            elif isinstance(node, ast.BinOp):
                left = _eval(node.left)
                right = _eval(node.right)
                if isinstance(node.op, ast.Add): return left + right
                if isinstance(node.op, ast.Sub): return left - right
                if isinstance(node.op, ast.Mult): return left * right
                if isinstance(node.op, ast.Div):
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    return left / right
                if isinstance(node.op, ast.Pow): return left ** right
                raise ValueError(f"Unsupported binary operator: {type(node.op)}")
            elif isinstance(node, ast.UnaryOp):
                operand = _eval(node.operand)
                if isinstance(node.op, ast.USub): return -operand
                if isinstance(node.op, ast.UAdd): return operand
                raise ValueError(f"Unsupported unary operator: {type(node.op)}")
            elif isinstance(node, ast.Expr):
                return _eval(node.value)
            else:
                raise ValueError(f"Unsupported expression element: {type(node)}")

        result = _eval(tree.body)
        return float(result)

    except (SyntaxError, TypeError, RecursionError):
        # SyntaxError handles mismatched parentheses or invalid characters
        raise ValueError("Invalid mathematical expression.")
    except ZeroDivisionError:
        raise ZeroDivisionError("division by zero")
    except Exception as e:
        # Catch any other unexpected errors as ValueErrors
        if isinstance(e, ZeroDivisionError):
