import re

def is_valid_email(s: str) -> bool:
    # Check if there is exactly one '@'
    if s.count('@') != 1:
        return False

    local, domain = s.split('@')

    # Local part validation
    # 1. Must start and end with alphanumeric
    if not local or not (local[0].isalnum() and local[-1].isalnum()):
        return False

    # 2. Allowed characters: alphanumeric, '.', '_', '-'
    # 3. No consecutive separators
    for i in range(len(local)):
        char = local[i]
        if not (char.isalnum() or char in '._-'):
            return False
        if i > 0 and char in '._-' and local[i-1] in '._-':
            return False

    # Domain part validation
    # 1. Must contain at least one dot separating at least two labels
    labels = domain.split('.')
    if len(labels) < 2:
        return False

    for i, label in enumerate(labels):
        # 2. Each label must be non-empty and consist only of alphanumeric characters
        if not label or not label.isalnum():
            return False

        # 3. The last label must consist of at least two ASCII letters only
        if i == len(labels) - 1:
            if len(label) < 2 or not label.isalpha():
                return False

    return True
