        return False

    local, domain = s.split('@')

    # Local part validation:
    # 1. Starts and ends with letter or digit
    # 2. Contains only letters, digits, '.', '_', '-'
    # 3. No two separator characters are next to each other
    if not local or not (local[0].isalnum() and local[-1].isalnum()):
        return False

    # Check for invalid characters and consecutive separators
    for i in range(len(local)):
        char = local[i]
        if not (char.isalnum() or char in '._-'):
            return False
        if i > 0:
            prev = local[i-1]
            if char in '._-' and prev in '._-':
                return False

    # Domain part validation:
    # 1. At least two labels separated by a single dot
    # 2. Each label is a non-empty sequence of ASCII letters and digits
    # 3. The last label must consist of at least two ASCII letters only
    labels = domain.split('.')
    if len(labels) < 2:
        return False

    for i in range(len(labels)):
        label = labels[i]
        if not label:
            return False

        if i < len(labels) - 1:
            # All labels except the last: alphanumeric
            if not label.isalnum():
                return False
        else:
            # Last label: at least two characters, letters only
            if len(label) < 2 or not label.isalpha():
                return False

    return True

