def is_allowed_webhook(url: str) -> bool:
    # Check for backslash, space, or control characters
    for char in url:
        if char == '\\' or ord(char) < 32 or ord(char) == 127:
            return False

    # Case-insensitive check for https:// prefix
    if not url.lower().startswith('https://'):
        return False

    try:
        parsed = urlparse(url)
        # urlparse might fail or return empty netloc if URL is malformed
        netloc = parsed.netloc
        if not netloc:
            return False

        # Extract host: remove userinfo and port
        # netloc format: [user:pass@]host[:port]
        if '@' in netloc:
            host_port = netloc.split('@')[-1]
        else:
            host_port = netloc

        if ':' in host_port:
            host, port = host_port.rsplit(':', 1)
            # Port must be absent (handled by logic) or 443
            if port != '443':
                return False
        else:
            host = host_port

        # Remove trailing dot for DNS validation
        dns_host = host[:-1] if host.endswith('.') else host

        # Host cannot be empty
        if not dns_host:
            return False

        # Check for localhost (case-insensitive)
        if dns_host.lower() == 'localhost' or dns_host.lower().endswith('.localhost'):
            return False

        # DNS Name validation:
        # 1. Two or more labels separated by dots
        labels = dns_host.split('.')
        if len(labels) < 2:
            return False

        # 2. Each label is non-empty and consists of ASCII letters, digits, and hyphens
        for label in labels:
            if not label:
                return False
            if not re.match(r'^[a-zA-Z0-9-]+$', label):
                return False

        # 3. The last label must consist only of letters
        if not re.match(r'^[a-zA-Z]+$', labels[-1]):
