from jinja2 import Template, Undefined

class SilentUndefined(Undefined):
    def __str__(self):
        return ""
    def __getattr__(self, name):
        return self

def render_notification(template: str, variables: dict) -> str:
    """
    Renders a notification template using jinja2.
    Placeholders are replaced by values from the variables dictionary.
    Missing keys are replaced by empty strings.
    """
    # Create a Template object with a custom Undefined class to handle missing keys as empty strings
    # and ensure no auto-escaping is applied.
    tmpl = Template(template, undefined=SilentUndefined)
    return tmpl.render(**variables)

